typedef struct{uint8_t*b;size_t n;uint32_t base,size;}Exe;
static uint32_t le32(const uint8_t*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}static int16_t sx16(uint32_t w){return(int16_t)(w&0xffff);}
static uint32_t word(const Exe*e,uint32_t va){if(va<e->base||va-e->base+4>e->size)return 0;return le32(e->b+0x800+(va-e->base));}
static int writes(uint32_t w,int r){unsigned op=w>>26,rt=(w>>16)&31,rd=(w>>11)&31;if(!r)return 0;if(op==0)return rd==r&&((w&63)!=8&&(w&63)!=9);if(op==2||op==3||op==4||op==5||op==6||op==7)return 0;return rt==r;}
static void expr(const Exe*e,uint32_t before,int reg,int depth,char*out,size_t z){if(depth>8){snprintf(out,z,"r%d?",reg);return;}if(reg==0){snprintf(out,z,"0");return;}uint32_t floor=before>0x180?before-0x180:e->base;if(floor<e->base)floor=e->base;for(uint32_t p=before&~3u;p>=floor+4;p-=4){uint32_t at=p-4,w=word(e,at);if(!writes(w,reg))continue;unsigned op=w>>26,rs=(w>>21)&31,rt=(w>>16)&31,rd=(w>>11)&31,fn=w&63,sh=(w>>6)&31;char a[160],b[160];(void)rd;if(op==15){snprintf(out,z,"0x%08x",(w&0xffff)<<16);return;}if(op==9){expr(e,at,rs,depth+1,a,sizeof a);if(rs==0)snprintf(out,z,"%d",sx16(w));else snprintf(out,z,"(%s%+d)",a,sx16(w));return;}if(op==13){expr(e,at,rs,depth+1,a,sizeof a);if(rs==0)snprintf(out,z,"0x%x",w&0xffff);else snprintf(out,z,"(%s|0x%x)",a,w&0xffff);return;}if(op==12){expr(e,at,rs,depth+1,a,sizeof a);snprintf(out,z,"(%s&0x%x)",a,w&0xffff);return;}if(op==32||op==36||op==33||op==37||op==35){expr(e,at,rs,depth+1,a,sizeof a);const char*t=op==32?"s8":op==36?"u8":op==33?"s16":op==37?"u16":"u32";snprintf(out,z,"mem%s[%s%+d]",t,a,sx16(w));return;}if(op==0&&(fn==33||fn==32||fn==37)){expr(e,at,rs,depth+1,a,sizeof a);expr(e,at,rt,depth+1,b,sizeof b);snprintf(out,z,"(%s%s%s)",a,fn==37?"|":"+",b);return;}if(op==0&&fn==0){expr(e,at,rt,depth+1,a,sizeof a);if(sh==0)snprintf(out,z,"%s",a);else snprintf(out,z,"(%s<<%u)",a,sh);return;}if(op==0&&fn==2){expr(e,at,rt,depth+1,a,sizeof a);snprintf(out,z,"(%s>>%u)",a,sh);return;}snprintf(out,z,"r%d@%08x",reg,at);return;}snprintf(out,z,"r%d?",reg);}
static const char*name(uint32_t t){switch(t){case 0x80025f54:return"sprite_tile";case 0x800260f8:return"glyph";case 0x80026588:return"glyph_tinted";case 0x80026df4:return"upload_anim_frame";default:return"other";}}
static int interesting(uint32_t t){return t==0x80025f54||t==0x800260f8||t==0x80026588||t==0x80026df4;}
int main(int ac,char**av){if(ac!=2){fprintf(stderr,"usage: %s exe\n",av[0]);return 2;}FILE*f=fopen(av[1],"rb");if(!f){perror(av[1]);return 2;}fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);uint8_t*b=malloc(n);if(!b||fread(b,1,n,f)!=(size_t)n)return 2;fclose(f);if(n<0x800||memcmp(b,"PS-X EXE",8)){fputs("not PS-X EXE\n",stderr);return 3;}Exe e={b,(size_t)n,le32(b+0x18),le32(b+0x1c)};if((uint64_t)e.size+0x800>e.n)return 3;printf("EXE base=0x%08x text_size=0x%x\n",e.base,e.size);uint32_t ranges[][2]={{0x80052574,0x800526f4},{0x800526f4,0x80053638}};unsigned calls=0;for(unsigned q=0;q<2;q++){printf("RANGE 0x%08x..0x%08x\n",ranges[q][0],ranges[q][1]);for(uint32_t pc=ranges[q][0];pc<ranges[q][1];pc+=4){uint32_t w=word(&e,pc);if((w>>26)!=3)continue;uint32_t t=((pc+4)&0xf0000000)|((w&0x03ffffff)<<2);if(!interesting(t))continue;char x[4][200];for(int a=0;a<4;a++)expr(&e,pc+8,4+a,0,x[a],sizeof x[a]);printf("CALL pc=0x%08x target=0x%08x %s a0=%s a1=%s a2=%s a3=%s delay=0x%08x\n",pc,t,name(t),x[0],x[1],x[2],x[3],word(&e,pc+4));calls++;}}
printf("SUMMARY interesting_calls=%u immutable_input=true\n",calls);free(b);return 0;}
